<?php if(!defined('ABSPATH')){exit;}$article=$state->article();$view=$article?(new AICS_Manual_Featured_Image_Service())->view($article['id'],get_current_user_id()):array();$attachment=$view['attachment']??null; ?>
<div><header class="aics-wizard-step-header"><p class="aics-eyebrow"><?php esc_html_e('Step 4 of 6','ai-content-studio');?></p><h2 tabindex="-1"><?php esc_html_e('Featured Image','ai-content-studio');?></h2><p><?php echo esc_html(AICS_Featured_Image_State::status_label($article['featured_image_status']??'not_requested'));?></p></header><?php if(is_array($attachment)):?><div class="aics-wizard-image"><img src="<?php echo esc_url($attachment['url']);?>" alt="<?php echo esc_attr($attachment['alt']);?>"><form class="aics-wizard-form" data-operation="save_alt"><label class="aics-field-label" for="aics-wizard-alt"><?php esc_html_e('Image alt text','ai-content-studio');?></label><input id="aics-wizard-alt" type="text" name="featured_image_alt_text" maxlength="250" value="<?php echo esc_attr($attachment['alt']);?>"><button class="button" type="submit"><?php esc_html_e('Save Alt Text','ai-content-studio');?></button></form></div><?php else:?><div class="aics-wizard-empty"><p><?php esc_html_e('Create and attach one image using the configured featured-image pipeline.','ai-content-studio');?></p><?php if(!empty($view['provider_ready'])):?><button class="button button-primary" type="button" data-aics-operation="generate_image"><?php esc_html_e('Generate Featured Image','ai-content-studio');?></button><?php else:?><p><?php esc_html_e('Configure image generation in Settings, or continue without an image.','ai-content-studio');?></p><?php endif;?></div><?php endif;?><footer class="aics-wizard-actions"><button class="button" type="button" data-aics-step="article"><?php esc_html_e('Back','ai-content-studio');?></button><button class="button button-primary" type="button" data-aics-operation="generate_seo"><?php esc_html_e(is_array($attachment)?'Next: Prepare SEO':'Skip Image and Prepare SEO','ai-content-studio');?></button></footer></div>
